versions.safe:
router.get("/support/orders/:id", requireSignedIn, async (req, res) => {
  const order = await orders.findById(req.params.id);
  if (!order || !req.user.permissions.includes("support:orders") || order.guestId !== req.user.guestId) return res.status(403).end();
  res.json(order);
});
